export const outputPrompts = {
  "kratos.png": "Role: You are a concept artist and image-generation director producing key art for a Norse-mythology game world on a fan website.\n\n# Personality\nPrecise, cinematic and restrained. Favour realism and mood over spectacle.\n\n# Goal\nGenerate one photorealistic landscape key-art image of a battle-hardened warrior standing in a blizzard before a ruined mountain tower.\n\n# Success criteria\n- Subject: a bald, heavily muscled warrior with a thick dark beard and a scowling, intense stare straight into the camera.\n- A red painted stripe runs over his left eye and scalp and down across his shoulder and chest.\n- Costume: a scaled leather pauldron on his left shoulder, a thick leather strap diagonally across his bare chest, a layered leather belt, worn wrist bracers and a tattered red-and-dark cloth skirt.\n- He grips the handle of an axe low at his right side; the blade sits out of frame at the bottom left.\n- Background: a jagged snow-covered mountain peak under a dark storm sky, a ruined stone tower with arched openings on the right, faint warm lights in distant huts, two ravens in flight at the upper left, and heavy drifting snow.\n- Lighting: cold blue-grey ambient light with a soft rim light on his shoulders and head; skin keeps its natural warmth against the cold palette.\n- Framing: medium shot from the thighs up, subject slightly left of centre, shallow depth of field on the background.\n\n# Constraints\n- Landscape orientation, 3:2 (1536 × 1024).\n- Photorealistic cinematic render, not cartoon or anime.\n- No text, logos, watermarks or UI.\n- One character only.\n\n# Output\nA single finished image. No written commentary.\n\n# Stop rules\nIf the face, beard or red markings come out inconsistent, regenerate rather than deliver. Stop once the success criteria are all visible.",
  "Atreus.png": "Role: You are a concept artist producing character key art for a Norse-mythology game world on a fan website.\n\n# Personality\nQuiet, grounded and cinematic. The mood is watchful, not heroic posing.\n\n# Goal\nGenerate one photorealistic landscape portrait of a young archer standing in a snowy valley at dusk.\n\n# Success criteria\n- Subject: a boy of about twelve with short, spiky auburn hair, pale blue eyes and a serious, wary expression, gazing off to the right of frame.\n- Costume: a grey fur-trimmed tunic with two crossed leather straps over the chest, a mustard-yellow undershirt collar, a layered leather belt and dark sleeves.\n- A quiver of red-fletched arrows over his left shoulder; a wooden recurve bow held low in his right hand across the bottom of the frame.\n- Background: dark pine trees and snow-covered rocks on the left; a ruined stone archway gate with warm, glowing lights on the right; a frozen river and jagged mountains beyond; light snowfall.\n- Lighting: cold blue storm light with a warm glow from the ruins; soft rim light on his hair and fur collar.\n- Framing: medium shot from the waist up, subject left of centre, background softly out of focus.\n\n# Constraints\n- Landscape orientation, 3:2 (1536 × 1024).\n- Photorealistic cinematic render.\n- No text, logos, watermarks or UI.\n\n# Output\nA single finished image with no commentary.\n\n# Stop rules\nRegenerate if the face looks older than a child or the bow and quiver are missing. Stop when every success criterion is met.",
  "freya.png": "Role: You are a concept artist producing character key art for a Norse-mythology game world on a fan website.\n\n# Personality\nSolemn, mysterious and elegant.\n\n# Goal\nGenerate one photorealistic landscape portrait of a sorceress standing above a snowy valley with a lit fortress behind her.\n\n# Success criteria\n- Subject: a woman in her forties with long, dark, textured braids falling past her shoulders, smoky eyes and a calm, distant expression, looking off to the right.\n- Costume: layered dark leather and cloth wrap armour, a large round embossed metal belt disc, cloth wraps on her upper arms, a thin cord necklace with an amber pendant and small beads, a draped hooded cloak.\n- Background: tall dark pines and snowy cliffs on the left; a vast dark fortress with many warm-lit windows and a stone arch bridge on the right; sharp snow-capped peaks under a stormy sky; faint falling snow.\n- Lighting: soft cool light from the overcast sky, warm glints from the fortress windows, gentle rim light on her hair.\n- Framing: medium shot from the waist up, subject left of centre, background in soft focus.\n\n# Constraints\n- Landscape orientation, 3:2 (1536 × 1024).\n- Photorealistic cinematic render.\n- No text, logos, watermarks or UI.\n\n# Output\nA single finished image with no commentary.\n\n# Stop rules\nRegenerate if the pendant, braids or fortress are missing. Stop when all success criteria are met.",
  "raiden.png": "Role: You are a key-art designer creating a character poster for a martial-arts fighting-game world on a fan website.\n\n# Personality\nBold, dramatic and polished, like an official character-select poster.\n\n# Goal\nGenerate one photorealistic portrait-orientation character poster of a thunder god, with a title set in the image.\n\n# Success criteria\n- Subject: a man in a wide conical woven straw hat with glowing white-blue eyes and a stern expression, standing three-quarter to the camera.\n- Costume: a white robe with navy-blue panels and gold trim, a high collar, navy shoulder armour with gold edging, a round navy emblem on the right shoulder and on the belt buckle, braided red rope cords at the waist, dark forearm bracers.\n- Crackling blue-white lightning arcs from both open hands.\n- Background: a night storm full of branching blue lightning, silhouetted pagoda temples on both sides, reflective wet ground.\n- Top left: a large, softly glowing circular dragon emblem.\n- A thin glowing blue border framing the whole poster.\n- Bottom: the title \"RAIDEN\" in large off-white, slightly distressed serif capitals, and beneath it \"GOD OF THUNDER\" in small blue capitals flanked by thin line ornaments.\n- Lighting: cold electric blue key light from the lightning with gold highlights on the trim.\n\n# Constraints\n- Portrait orientation, 2:3 (1024 × 1536).\n- Text must be spelled exactly \"RAIDEN\" and \"GOD OF THUNDER\".\n- No other text, no watermark, no signature.\n\n# Output\nA single finished poster image with no commentary.\n\n# Stop rules\nIf either title is misspelled or cropped, regenerate. Stop when the text is correct and all success criteria are met.",
  "reptile.png": "Role: You are a key-art designer creating a character poster for a martial-arts fighting-game world on a fan website.\n\n# Personality\nMenacing, atmospheric and polished.\n\n# Goal\nGenerate one photorealistic portrait-orientation character poster of a reptilian ninja assassin, with a title and tagline set in the image.\n\n# Success criteria\n- Subject: a hooded, masked ninja with glowing yellow reptilian eyes, crouched low and lunging toward the camera.\n- Costume: dark green scaled armour with a hood and face mask, a scaled chest plate, a round belt emblem, a hanging front panel with a reptile-head motif, clawed gauntlets.\n- A curved green-edged dagger in his right hand; his left clawed hand extended toward the camera, dripping green slime.\n- Background: a misty jungle swamp with hanging vines, an ancient stepped stone temple with glowing green windows, a glowing green full moon, and a crocodile emerging from the water at the bottom right.\n- Top left: a large circular dragon emblem in green and gold.\n- A thin green border framing the whole poster.\n- Bottom: the title \"REPTILE\" in large gold-green distressed serif capitals, the tagline \"HIDE IN THE SHADOWS. STRIKE IN SILENCE.\" in small green capitals beneath it with line ornaments, and a small reptile-skull icon centred below.\n- Lighting: sickly green ambient light with rim light on the scales.\n\n# Constraints\n- Portrait orientation, 2:3 (1024 × 1536).\n- Text must be spelled exactly as given.\n- No other text, no watermark, no signature.\n\n# Output\nA single finished poster image with no commentary.\n\n# Stop rules\nRegenerate if any text is misspelled or cut off. Stop once the text is correct and all success criteria are met.",
  "hero.mp4": "<role>\nYou are a cinematic video director animating a still piece of game key art with Google Veo.\n</role>\n\n<instructions>\n1. Use the attached image as the first frame and keep the warrior's face, beard, red markings and costume identical throughout.\n2. Keep him standing in place with a menacing stare; add only subtle life: a slow breath through the chest and a slight tightening of the brow.\n3. Animate the environment: heavy snow drifting diagonally across the frame, fog rolling low through the valley, and a flock of ravens gathering and circling the ruined stone tower on the right.\n4. Camera: a very slow, steady push-in toward the warrior.\n5. Audio: howling blizzard wind, distant raven calls and a low, ominous drone.\n</instructions>\n\n<constraints>\n- No change to the character's identity, pose or costume.\n- No new characters, text, logos or watermarks.\n- No cuts; one continuous shot.\n</constraints>\n\n<output_format>\nOne continuous 8-second clip, 24 fps, 16:9, 720p or higher, with generated audio.\n</output_format>\n\n<context>\nThe image is landscape key art of a bald, bearded warrior in a blizzard before a mountain tower. It is the hero moment for the God of War world of a fan website. The final site uses a 2.6-second trim of this clip.\n</context>\n\n<task>\nAnimate the attached image into a slow, atmospheric hero shot with snow, fog and circling ravens.\n</task>\n\n<final_instruction>\nIdentity consistency comes first: if his face or markings would change, reduce the motion rather than alter him.\n</final_instruction>",
  "boy.mp4": "<role>\nYou are a cinematic video director animating character key art with Google Veo.\n</role>\n\n<instructions>\n1. Use the attached image as the first frame and keep the boy's face, hair, costume, quiver and bow identical throughout.\n2. Action: he turns his head toward the camera, raises his bow, draws a red-fletched arrow from his quiver, nocks it and pulls the string back to a full, steady aim across the frame.\n3. His expression shifts from wary to focused as he aims.\n4. Environment: light snowfall that thickens into a driving blizzard by the end of the shot; mist drifting past the glowing ruined archway.\n5. Camera: a slow push-in that finishes in a medium close-up on his aiming pose.\n6. Audio: rising wind, the creak of the bowstring under tension, a held breath before the final aim.\n</instructions>\n\n<constraints>\n- Keep the boy's anatomy and hands correct while drawing the bow.\n- No new characters, text, logos or watermarks.\n- One continuous shot, no cuts.\n</constraints>\n\n<output_format>\nOne continuous 8-second clip, 24 fps, 16:9, 720p, with generated audio.\n</output_format>\n\n<context>\nThe image is landscape key art of a young archer in a snowy valley at dusk, for the God of War world of a fan website.\n</context>\n\n<task>\nAnimate the attached image so the boy raises his bow, nocks an arrow and takes aim as the snow becomes a blizzard.\n</task>\n\n<final_instruction>\nKeep every frame consistent with the source image's character and lighting.\n</final_instruction>",
  "freya.mp4": "<role>\nYou are a cinematic video director animating a character portrait with Veo in the Gemini app.\n</role>\n\n<instructions>\n1. Use the attached portrait as the first frame and keep the woman's face, braided hair, fur cape and leather armour identical.\n2. She slowly turns her head to look into the distance, her expression wary and troubled.\n3. The wind lifts loose strands of her hair and gently sways her braids and fur cape.\n4. Gentle snow falls around her; a raven flies across the sky behind her; dark clouds drift past the snowy peaks and the dark castle on the right.\n5. Camera: a slow, dramatic push-in that ends in a close-up of her face.\n6. Audio: soft wind, falling snow, and a single distant raven call.\n</instructions>\n\n<constraints>\n- No change to her identity, age or costume.\n- No text, logos or watermarks.\n- One continuous shot.\n</constraints>\n\n<output_format>\nOne continuous clip of about 4 seconds, 24 fps, 9:16 vertical, 720 × 1280, with generated audio.\n</output_format>\n\n<context>\nThe source portrait shows a battle-worn warrior woman with braided brown hair, a fur-trimmed cape and studded leather armour, standing before snowy mountains and a dark castle. It is for the God of War world of a fan website. This clip was not made from freya.png, which shows a different character.\n</context>\n\n<task>\nAnimate the attached portrait into a slow, windswept push-in toward her face.\n</task>\n\n<final_instruction>\nPreserve the face exactly; motion must come from the head turn, wind, snow and camera only.\n</final_instruction>",
  "gow.mp4": "<role>\nYou are a film director and editor building a short, epic fantasy sequence with Google Veo, using consistent characters across several shots.\n</role>\n\n<instructions>\n1. Keep the same two characters in every shot:\n   - A bald, heavily muscled, bearded warrior with a red painted stripe, dark leather armour with a fur shoulder piece, and a battle axe whose blade glows with blue frost runes.\n   - A boy of about twelve with short brown hair, a grey fur-trimmed tunic, a mustard-yellow collar, a quiver of red arrows and a wooden bow.\n2. Setting throughout: a rocky, snow-covered mountain ledge above a vast frozen valley, ancient ruins and a cliff fortress marked with glowing blue runes, under a dark storm sky with branching lightning.\n3. Shot list, in order:\n   - Shot 1 (about 0–1.5 s): wide shot from behind. Both characters stand on the ledge looking out at the valley. Lightning strikes the peaks; embers drift up from a small fire in the bottom-right corner.\n   - Shot 2 (about 1.5–3 s): over-the-shoulder close-up of the warrior resting the glowing axe on his shoulder as blue lightning crackles along the blade.\n   - Shot 3 (about 3–4.5 s): close-up of the boy looking up in wonder as a glowing blue energy orb forms in his open palm.\n   - Shot 4 (about 4.5–6 s): medium close-up of the boy drawing his bow; the arrow ignites into crackling blue lightning.\n   - Shot 5 (about 6–8.5 s): low-angle shot of the warrior roaring and raising the axe overhead, then leaping and slamming it down in slow motion.\n   - Shot 6 (about 8.5–12 s): wide shot of the impact. Huge jagged ice shards erupt from the ground around both characters; the boy holds his glowing arrow at full draw beside the warrior.\n4. Lighting: moody cool blue and grey, lit by lightning flashes and the glow of the runes, axe and arrow.\n5. Audio: thunder, crackling electricity, a rising orchestral score, and a heavy ice explosion on the slam.\n</instructions>\n\n<constraints>\n- The two characters must look identical in every shot.\n- No text, logos or watermarks.\n- Photorealistic cinematic style; no cartoon look.\n</constraints>\n\n<output_format>\nA single edited sequence of about 12 seconds with hard cuts between shots, 16:9. Generate at 1080p and export upscaled to 4K (3840 × 2160), with generated audio.\n</output_format>\n\n<context>\nThis is the trailer sequence for the God of War world of a fan website. Veo clips are short, so generate the shots as separate clips using a shared character reference, then join and export them.\n</context>\n\n<task>\nCreate a six-shot fantasy sequence of a warrior and a boy on a stormy mountain, ending in a slow-motion axe slam that erupts into ice.\n</task>\n\n<final_instruction>\nHold character consistency above all; reuse the same reference images for every shot.\n</final_instruction>",
  "donut.mp4": "<role>\nYou are a commercial food-film director animating a whimsical 3D product still with Google Veo.\n</role>\n\n<instructions>\n1. Use the attached image as the first frame and keep its composition, colours and textures.\n2. Subject: a giant glossy pink-frosted donut covered in rainbow sprinkles, resting on a curved metallic pink mechanical platform, with smaller chocolate- and pink-frosted donuts beside it and thick pink glaze pooling and dripping around the base.\n3. Environment motion: small round colourful candies drift and tumble through the air in slow motion; one large glossy pink candy sphere passes close in front of the lens, briefly out of focus; fluffy pink clouds roll slowly behind.\n4. Camera: a smooth, slow push-in combined with a gentle arc to the right, revealing the large pink gear wheels and pipes of the steampunk candy factory in the background.\n5. Glaze on the donut drips slowly and glistens in the light.\n6. Audio: a light, dreamy, playful music bed with soft whooshes as candies float past.\n</instructions>\n\n<constraints>\n- Keep the hyper-realistic 3D look; no cartoon flattening.\n- No text, logos or watermarks.\n- One continuous shot.\n</constraints>\n\n<output_format>\nOne continuous 8-second clip, 24 fps, 16:9, 1080p, with generated audio. The 3:2 source image will sit inside side bars.\n</output_format>\n\n<context>\nThis clip is the hero background for the donut world of a dessert-shop website. It plays behind headline text, so the motion must stay slow and smooth.\n</context>\n\n<task>\nAnimate the attached donut still with drifting candies and a slow push-in and arc around the giant donut.\n</task>\n\n<final_instruction>\nKeep the motion gentle enough to loop behind website text.\n</final_instruction>",
  "icecream.mp4": "<role>\nYou are a commercial food-film director creating a dreamy dessert shot with Google Veo.\n</role>\n\n<instructions>\n1. Subject: a decadent four-scoop ice cream sundae in a pink-and-white striped paper bowl. Scoops of strawberry, chocolate, mint chocolate chip and caramel, topped with a glossy cherry with its stem, red and caramel syrup drizzles, sprinkles, two chocolate-striped wafer rolls and a heart-shaped cookie.\n2. Setting: the bowl sits on a glossy wet pink surface scattered with melted scoops, colourful candy spheres and an overturned ice cream cone on the left.\n3. Background: a soft pastel gradient sky in pinks, lavenders and pale blues.\n4. Motion: shiny colourful candy spheres drift slowly down through the air; a burst of sprinkles scatters upward around the bowl; syrup glistens as it slowly runs down the scoops.\n5. Camera: a slow, smooth push-in from a wide shot to a close-up of the top of the sundae.\n6. Lighting: soft, bright, magical light that highlights the melting textures.\n7. Audio: a gentle, sweet music bed with soft sparkling sound effects.\n</instructions>\n\n<constraints>\n- Hyper-realistic 3D render quality.\n- No text, logos or watermarks.\n- One continuous shot, centred composition.\n</constraints>\n\n<output_format>\nOne continuous 8-second clip, 24 fps, 16:9, 1080p, with generated audio.\n</output_format>\n\n<context>\nThis clip is the hero background for the ice cream world of a dessert-shop website and plays behind headline text.\n</context>\n\n<task>\nCreate a slow push-in toward a four-scoop sundae as candies drift through a pastel sky.\n</task>\n\n<final_instruction>\nKeep the sundae centred and the motion slow enough to sit behind text.\n</final_instruction>",
  "smoothies.mp4": "<role>\nYou are a commercial beverage-film director creating a fresh fruit smoothie shot with Google Veo.\n</role>\n\n<instructions>\n1. Subject: three tall glasses of smoothie side by side — green on the left, bright pink in the middle and orange on the right. The pink glass has a pink-and-white striped straw, the orange glass a yellow striped straw, and each is topped with fruit and mint.\n2. Setting: the glasses stand on an ornate round woven bamboo tray with kiwi halves, strawberries, blueberries and diced mango arranged around them.\n3. Background: a dreamy sky of fluffy clouds in warm peach and golden-hour light.\n4. Motion: fresh strawberries, kiwi slices, blueberries, mango cubes and mint leaves fall and tumble in slow motion toward the camera; arcs of orange juice splash out at the start of the shot.\n5. Camera: a smooth, slow push-in from a wide shot to a medium close-up of the three glasses.\n6. Lighting: warm, glowing golden-hour backlight with soft highlights on the fruit.\n7. Audio: an upbeat, fresh music bed with soft splashes and light whooshes as fruit falls.\n</instructions>\n\n<constraints>\n- Hyper-realistic look.\n- No text, logos or watermarks.\n- One continuous shot.\n</constraints>\n\n<output_format>\nOne continuous 8-second clip, 24 fps, 16:9, 1080p, with generated audio.\n</output_format>\n\n<context>\nThis clip is the hero background for the smoothie world of a dessert-shop website and plays behind headline text.\n</context>\n\n<task>\nCreate a slow push-in toward three smoothies as fresh fruit falls through a golden-hour sky.\n</task>\n\n<final_instruction>\nKeep all three glasses in frame and the motion smooth enough to sit behind text.\n</final_instruction>",
  "thickshake.mp4": "<role>\nYou are a commercial food-film director animating a dramatic dessert still with Google Veo.\n</role>\n\n<instructions>\n1. Use the attached image as the first frame and keep the glass, toppings and colours unchanged.\n2. Subject: a tall glass of chocolate cookie milkshake overflowing with whipped cream, drizzled with glossy chocolate syrup that runs down the glass, topped with whole chocolate sandwich cookies and a red straw.\n3. Motion: at the start, a slow-motion splash of milky chocolate erupts around the base of the glass, then settles into a spreading puddle scattered with cookie crumbs; whole cookies and chocolate chunks float and rotate slowly in mid-air; wispy smoke curls around the glass along the dark surface.\n4. Background: a moody deep-purple gradient with a soft glow behind the glass.\n5. Camera: a very slow, subtle push-in, keeping the glass centred.\n6. Lighting: dramatic high-contrast side and back light on the cream, syrup and cookies.\n7. Audio: a deep, rich, moody music bed with a soft liquid splash at the start.\n</instructions>\n\n<constraints>\n- Hyper-realistic look; no cartoon style.\n- No text, logos or watermarks.\n- One continuous shot.\n</constraints>\n\n<output_format>\nOne continuous 8-second clip, 24 fps, 16:9, 1080p, with generated audio. The 3:2 source image will sit inside side bars.\n</output_format>\n\n<context>\nThis clip is the hero background for the milkshake world of a dessert-shop website. It is the darkest and moodiest of the four dessert worlds.\n</context>\n\n<task>\nAnimate the attached milkshake still with a slow-motion splash, floating cookies and drifting smoke.\n</task>\n\n<final_instruction>\nKeep the glass sharp and centred; all motion comes from the splash, cookies, smoke and a very slow push-in.\n</final_instruction>",
  "background.jpeg": "Role: You are an architectural interior photographer and art director creating the full-screen hero background for the website of VanWood, a premium manufacturer of plywood, flush doors and block boards in Raipur, Chhattisgarh.\n\n# Personality\nRefined, warm and understated. Luxury through restraint, not decoration.\n\n# Goal\nGenerate one photorealistic, ultra-wide luxury interior image to sit behind the website's headline and three product callouts.\n\n# Success criteria\n- A tall, elegant dark walnut flush door with rich natural vertical wood grain, a slim dark frame and a minimal dark handle, positioned exactly in the centre.\n- A deep matte black-brown wall with subtle vertical wood panelling behind the door.\n- On the right: built-in dark wooden shelves with concealed warm LED strips, holding dark ceramic vases, small green plants and a few books, and a small black cylindrical pendant light hanging on a thin cord.\n- On the left, low in the frame: a long, low dark wooden cabinet with a vase and a small plant.\n- Warm cinematic amber light from the LED strips and pendant, a subtle warm glow around the door edges, and soft, realistic shadows and reflections.\n- A symmetrical, spacious composition whose left third stays dark and empty enough to carry white headline text.\n- It reads as a premium studio photograph of a modern Indian luxury interior, not a 3D render.\n\n# Constraints\n- Landscape, 16:9 wide, suitable as a full-width website hero background.\n- No people.\n- No text, logos, labels, buttons, annotations, UI elements or decorative graphics.\n- Ultra-realistic materials and highly detailed wood texture.\n\n# Output\nA single finished image with no commentary.\n\n# Stop rules\nRegenerate if any text or UI appears, or if the door is not centred. Stop when every success criterion is met.",
  "door.mp4": "<role>\nYou are a senior front-end engineer and motion designer who builds premium scroll-driven storytelling sections for manufacturing brands.\n</role>\n\n<goal>\nBuild the \"How a Door Is Born\" process section for the VanWood website: a pinned, scroll-driven story that assembles a flush door layer by layer across eight steps.\n</goal>\n\n<context>\nVanWood manufactures plywood, flush doors and block boards in Raipur, Chhattisgarh. The site uses a dark, warm, wood-toned luxury aesthetic: near-black brown backgrounds, amber accents, a high-contrast serif for headings and a clean sans-serif for body text. The main navigation has Home, Our Story, Our Products, Process, Gallery and Contact, plus a \"Request a Quote\" button; \"Process\" is the active item on this page. A floating action stack sits at the bottom right: back-to-top, an AI assistant, phone and WhatsApp.\n</context>\n\n<instructions>\n1. Intro panel: a full-screen dark wood-grain background with the heading \"Open the Door to Excellence.\" and the subline \"Hover to let the light through. Step inside to see how a door is made.\" A warm light streak follows the cursor across the grain.\n2. Pin the section and drive it with scroll. Each step fades in on the left with:\n   - the eyebrow \"HOW A DOOR IS BORN\" in small, widely letter-spaced amber capitals;\n   - a very large, faded serif step number;\n   - a serif step title and a short description.\n3. Use exactly these eight steps and this copy:\n   - 01 Veneer Sheet: \"The layup begins face-down: a thin, hand-matched natural veneer sheet is laid as the door's outer skin.\"\n   - 02 Core Layer: \"Horizontal core sheet pieces are placed side by side to create the first core layer.\"\n   - 03 Glue Application: \"Adhesive glue is applied to core sheets with the help of a Glue Spreader machine to hold the layers firmly together.\"\n   - 04 Wooden Frame: \"Seasoned hardwood pieces are joined to make the outer frame of the door.\"\n   - 05 Core Filling: \"Vertical wood blocks are fitted tightly inside the frame for added strength and stability.\"\n   - 06 Second Core Layer: \"Another layer of horizontal core sheet pieces is placed over the blocks.\"\n   - 07 Glue Application: \"One more time adhesive glue is applied to core sheets with the help of a Glue Spreader machine to hold the layers firmly together.\"\n   - 08 Veneer Layer: \"A thin veneer sheet is placed on the surface and hot-pressed at 110°C.\"\n4. In the centre, a door visual builds up in sync: a reddish-brown striped veneer for 01 and 08, glossy amber glue sheets for 03 and 07, a patchwork of core blocks for 02, 05 and 06, and a hardwood frame outline for 04. Each new layer slides in and settles onto the stack, lit by a soft warm glow.\n5. Add a \"Skip this section\" button at the bottom left and a row of eight progress dashes at the bottom centre that fill as the steps advance.\n6. Respect prefers-reduced-motion: show all eight steps as a static vertical list with the door images inline, and no pinning.\n</instructions>\n\n<constraints>\n- Match the existing stack (React with GSAP ScrollTrigger and Lenis smooth scroll); do not add new animation libraries.\n- Use the step copy verbatim, including \"110°C\".\n- Keep text at WCAG AA contrast against the dark background.\n- Keep the layout responsive; on mobile, stack the text above the door visual.\n- Do not change the navigation, the header or other pages.\n</constraints>\n\n<input>\nStep titles and copy are listed in the instructions. Door layer images: veneer, glue, core blocks and frame renders supplied in the project's assets folder.\n</input>\n\n<examples>\n<example>\nInput: the user scrolls from step 02 to step 03.\nDesired output: \"02 Core Layer\" fades out, \"03 Glue Application\" and its description fade in, the third progress dash fills, and an amber glue sheet slides onto the door stack.\n</example>\n<example>\nInput: a visitor with prefers-reduced-motion enabled opens the page.\nDesired output: all eight steps appear as a static list with their door images and no scroll pinning.\n</example>\n</examples>\n\n<output_format>\n1. The section component and its styles.\n2. A short summary of the files changed.\n3. The exact steps you ran to verify it.\n</output_format>\n\n<final_check>\nBefore finishing, verify the result against the requirements above: all eight steps show the exact copy in order, the door visual stays in sync with the scroll, \"Skip this section\" jumps past the section, the progress dashes track the current step, reduced motion shows the static list, and no text falls below WCAG AA contrast.\n</final_check>",
  "rk-concepts.webp": "Role: You are a senior web designer presenting homepage concepts to a premium manufacturer of flush doors and plywood.\n\n# Personality\nEditorial, confident and restrained. Dark luxury, never flashy.\n\n# Goal\nGenerate one presentation image showing three full homepage design directions side by side for \"Radha Krishna — Industries · Doors · Ply\", all sharing one colour palette.\n\n# Success criteria\n- Three tall homepage mockups in equal columns, each with a small title above it: \"1. THE ARTISAN WORKSHOP (Same Color Palette)\", \"2. LUXURY PRODUCT GALLERY (Same Color Palette)\" and \"3. THE FUTURE FACTORY (My Choice)\".\n- Shared by all three: an \"RK\" monogram logo with \"Radha Krishna\" and \"INDUSTRIES · DOORS · PLY\"; a top navigation with a copper \"Request a Quote\" button; a stats row showing 2008, 15+ years experience and 5000+ projects completed.\n- Palette: deep walnut brown, rich coffee and wood gradients, warm copper and champagne accents, soft ivory text. Large editorial serif headings, modern sans-serif body text, generous whitespace.\n- Concept 1, The Artisan Workshop: a dark workshop hero with a single spotlight on a half-open walnut door; the headline \"CRAFTING ENTRANCES THAT LAST GENERATIONS.\" with \"GENERATIONS.\" in copper; \"Explore Products\" and \"Watch Our Story\" buttons; a six-step row (Wooden Frame, Solid Blocks, Core Sheet, Glue Layer, Veneer Layer, Finished Door) under \"BUILT WITH PRECISION. CREATED TO PERFECTION.\"; an \"OUR PROMISE\" row of four icons (Premium Materials, Precision Engineering, Long Lasting Durability, Timeless Design).\n- Concept 2, Luxury Product Gallery: the eyebrow \"PREMIUM FLUSH DOORS\" and headline \"ELEGANCE YOU CAN FEEL. QUALITY YOU CAN TRUST.\"; a walnut door on a glowing circular podium inside a copper light ring, flanked by six feature cards (Waterproof Technology, Borer Resistant, Premium Veneer, Fire Resistant, Eco Friendly, Termite Proof); an \"INSIDE EVERY DOOR\" exploded diagram labelled Premium Veneer, High Strength Glue, Core Sheet, Solid Wood Blocks and Outer Wooden Frame; an \"OUR RECENT PROJECTS\" row of three interior photographs.\n- Concept 3, The Future Factory: the headline \"ENGINEERED FOR THE FUTURE. CRAFTED TO PERFECTION.\" beside a door standing inside a glowing futuristic cylindrical chamber on a lit platform, with a floating \"QUALITY CHECK 100% PASSED\" data card; a five-step process row (Raw Materials, Advanced Manufacturing, Quality Testing, Premium Finishing, Ready For You); an \"ADVANCED MANUFACTURING TECHNOLOGY\" section with robotic arms in a factory; a \"TRUSTED BY ARCHITECTS & BUILDERS\" logo row.\n- Every column reads as a realistic, polished website screenshot.\n\n# Constraints\n- A landscape presentation board with three columns of equal width.\n- All text legible and spelled exactly as given.\n- Avoid Bootstrap-style layouts and generic stock templates.\n- No watermark.\n\n# Output\nA single presentation image with no commentary.\n\n# Stop rules\nRegenerate if the three concepts use different palettes or any headline is misspelled. Stop when all three concepts meet the success criteria.",
  "gameverse-portal.webp": "Role: You are a key-art and web designer creating the landing-page concept for GAMEVERSE, a fan website that presents three game universes.\n\n# Personality\nEpic, high-contrast and polished, like a flagship game-launch site.\n\n# Goal\nGenerate one photorealistic landing-page design image with three glowing portals, one for each game world.\n\n# Success criteria\n- Top navigation: a hexagonal \"G\" logo with \"GAMEVERSE\" (\"GAME\" in white, \"VERSE\" in purple); links HOME, UNIVERSES, TRAILERS, NEWS, COMMUNITY and ABOUT; social icons and a round sound toggle on the right.\n- A large metallic \"GAMEVERSE\" title centred at the top, with \"THREE WORLDS. ENDLESS BATTLES.\" beneath it between small diamond ornaments.\n- Three portals side by side across a dark, wet, rocky foreground that reflects their light:\n  - Left: a glowing blue portal ringed with Norse runes, titled \"GOD OF WAR\". A muscular warrior holding an axe and a young boy with a bow stand before it, seen from behind; inside it, snowy mountains under a stormy sky with ravens.\n  - Centre: a fiery orange portal titled \"MORTAL KOMBAT\" with a gold dragon emblem. A yellow-clad ninja and a blue-clad ninja stand before it, seen from behind; inside it, an ancient temple in flames.\n  - Right: a neon pink-red high-tech portal titled \"VALORANT\". A tactical agent stands before it, seen from behind; inside it, a neon cyberpunk cityscape.\n- Small slide indicators \"01\", \"02\" and \"03\" with dots beside and beneath the portals.\n- A stats bar with icons: 1,200+ CHARACTERS, 3 LEGENDARY UNIVERSES, 500+ ANIMATIONS, 2M+ PLAYERS, 50+ AWARDS.\n- A \"LATEST TRAILERS\" row of three thumbnail cards with play buttons, one per world, and a \"SCROLL TO EXPLORE\" mouse cue at the bottom.\n- Sparks and embers drifting across the whole scene, with dramatic, high-contrast lighting.\n\n# Constraints\n- Landscape, 3:2 (1536 × 1024).\n- All text spelled exactly as given and fully legible.\n- No watermark.\n\n# Output\nA single finished landing-page image with no commentary.\n\n# Stop rules\nRegenerate if any title or stat is misspelled, or a portal is missing its characters. Stop when all success criteria are met.",
  "triton-surface.mp4": "<role>\nYou are a cinematic director creating the opening shot of a continuous underwater descent with Google Flow.\n</role>\n\n<instructions>\n1. Subject: the Triton-X, a sleek deep-black research submersible with a glowing cyan ring around its front viewport, twin floodlights, a small manipulator arm and \"TRITON-X\" lettered on the hull. Use the supplied hero image of the vessel as the identity reference so it looks identical throughout.\n2. Opening: the submersible floats low on a calm, glassy sea at dusk, with a thin band of pink and orange sunset on the horizon and gentle ripples spreading from the hull.\n3. Action: the vessel moves forward and begins to submerge; water washes over the hull and the cyan ring reflects on the surface.\n4. Camera: start behind and slightly above the vessel, glide down with it through the waterline in one continuous move, and continue underwater as it dives.\n5. Underwater: clear blue water with sun rays filtering from the surface, rising air bubbles, and the floodlights switching on as the vessel descends and shrinks into the blue.\n6. The final frame shows the submersible small and centred in open blue water, so it can serve as the start image of the next clip.\n</instructions>\n\n<constraints>\n- The vessel's shape, colour, lighting and markings must match the reference image in every frame.\n- Photorealistic; no cartoon or game-like look.\n- No text other than the hull lettering; no logos or watermarks.\n- One continuous shot, no cuts.\n</constraints>\n\n<output_format>\nOne continuous 8-second clip, 24 fps, 16:9, 1080p.\n</output_format>\n\n<context>\nThis is clip one of five for Abyssal Ventures, a scroll-driven website where scrolling down descends 3,800 metres. Each clip's final frame is passed as the start image of the next, so the five generations join into one unbroken dive.\n</context>\n\n<task>\nCreate the opening clip: the Triton-X floating at dusk, submerging through the surface and diving into open blue water.\n</task>\n\n<final_instruction>\nKeep the vessel identical to the reference, and end on a clean frame the next clip can start from.\n</final_instruction>",
  "submarine-orbit.mp4": "<role>\nYou are a cinematic director creating a smooth camera orbit around a luxury submarine with Google Flow.\n</role>\n\n<instructions>\n1. Subject: a silver luxury passenger submarine with a long, rounded hull, a clear glass bubble nose, a row of large panoramic windows along its side, warm tan leather seats and soft interior lighting visible inside, a small conning tower with periscope masts, and side fins.\n2. Setting: a sunlit tropical coral reef in clear turquoise water, with branching and plate corals, schools of small yellow and blue fish, and sun rays streaming down from the surface.\n3. Camera: a smooth, continuous orbit around the submarine. Start on a cinematic front three-quarter view of the glass nose and travel around to a full side profile of the windows.\n4. The submarine holds its position, hovering just above the reef, while fish swim slowly past.\n5. Keep the motion steady enough to be extracted frame by frame for a scroll-driven sequence.\n</instructions>\n\n<constraints>\n- Ultra-photorealistic; no cartoon style and no CGI or game-like appearance.\n- No exaggerated science-fiction elements.\n- Stable, even camera speed with no shake or sudden moves.\n- No text, logos or watermarks.\n</constraints>\n\n<output_format>\nOne continuous clip of about 5 seconds, 24 fps, 16:9, 1080p.\n</output_format>\n\n<context>\nThe clip is for Abyssal Ventures, a scroll-driven website; its frames are scrubbed with the page scroll, so smooth, even motion matters more than drama.\n</context>\n\n<task>\nOrbit the camera from the front three-quarter view of a luxury glass-nosed submarine around to its side profile, above a sunlit coral reef.\n</task>\n\n<final_instruction>\nKeep the camera speed constant and the submarine perfectly steady throughout.\n</final_instruction>",
} as const

export type OutputFile = keyof typeof outputPrompts
